# MarketEcho public Windows launcher. No credentials are included.
powershell.exe -NoProfile -ExecutionPolicy Bypass -Command { $ErrorActionPreference = 'Stop'; $identity = [Security.Principal.WindowsIdentity]::GetCurrent(); try { $principal = New-Object Security.Principal.WindowsPrincipal($identity); $elevated = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } finally { $identity.Dispose() }; if ($elevated) { throw 'SETUP_STANDARD_USER_REQUIRED: chiudere questa console e aprire PowerShell normalmente, senza Esegui come amministratore. Ripetere la stessa riga di installazione. Nessuna installazione o pulizia avviata; le eventuali richieste UAC saranno limitate ai singoli prerequisiti Windows.' }; if ($PSVersionTable.PSEdition -eq 'Desktop') { $env:PSModulePath = (Join-Path $PSHOME 'Modules') + ';' + $env:PSModulePath }; if (-not [Environment]::Is64BitOperatingSystem -or $env:PROCESSOR_ARCHITECTURE -eq 'ARM64') { throw 'Serve Windows x64.' }; Get-ChildItem Env: | Where-Object { $_.Name -like 'GIT_*' -or $_.Name -in @('PYTHONPATH','PYTHONHOME') } | ForEach-Object { Remove-Item -LiteralPath ('Env:' + $_.Name) }; [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12; $d = Join-Path $env:TEMP ('MarketEcho-Setup-' + [guid]::NewGuid().ToString('N')); New-Item -ItemType Directory -Path $d | Out-Null; if (-not (Get-Command git -ErrorAction SilentlyContinue)) { Write-Host 'Preparo Git for Windows dalla fonte ufficiale...'; $r = Invoke-RestMethod 'https://api.github.com/repos/git-for-windows/git/releases/latest' -TimeoutSec 60; $a = @($r.assets | Where-Object { $_.name -match '^Git-[0-9.]+-64-bit\.exe$' }); if ($r.draft -or $r.prerelease -or $a.Count -ne 1) { throw 'Release Git non valida.' }; $a = $a[0]; if ($a.digest -notmatch '^sha256:[a-f0-9]{64}$' -or $a.browser_download_url -notmatch '^https://github\.com/git-for-windows/git/releases/download/') { throw 'Origine o hash Git non validi.' }; $f = Join-Path $d 'Git-Setup.exe'; Invoke-WebRequest -UseBasicParsing $a.browser_download_url -OutFile $f -TimeoutSec 300; if ((Get-FileHash -LiteralPath $f -Algorithm SHA256).Hash -ine $a.digest.Substring(7) -or (Get-AuthenticodeSignature -LiteralPath $f).Status -ne 'Valid') { throw 'Verifica Git fallita: installer non avviato.' }; $g = Join-Path $env:LOCALAPPDATA 'Programs\Git'; $p = Start-Process -FilePath $f -WindowStyle Hidden -PassThru -ArgumentList ('/VERYSILENT /SUPPRESSMSGBOXES /NORESTART /SP- /DIR="' + $g + '"'); if (-not $p.WaitForExit(300000) -or $p.ExitCode -notin @(0,3010)) { throw 'Installazione Git fallita o scaduta.' }; $env:PATH = (Join-Path $g 'cmd') + ';' + $env:PATH + ';' + [Environment]::GetEnvironmentVariable('Path','User') + ';' + [Environment]::GetEnvironmentVariable('Path','Machine'); }; $null = & git --version; if ($LASTEXITCODE) { throw 'Git non utilizzabile: setup interrotto.' }; $s = Join-Path $d 'Source'; & git clone -q --depth 1 -b main 'https://github.com/MarketEcho-AI/MarketEcho-AI.git' $s; if ($LASTEXITCODE) { throw 'Download main non riuscito: verificare accesso GitHub.' }; & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $s 'setup.ps1'); if ($LASTEXITCODE) { throw 'Setup interrotto: consultare il messaggio precedente.' }; }
